tries as (
  select c, (select public.split_shares(
      coalesce(nullif(c->>'seed', '')::uuid, '00000000-0000-4000-8000-000000000000'),
      (c->>'total')::numeric / 100, 'EUR', null,
      array(select jsonb_array_elements_text(coalesce(c->'spec'->'among', '[]')))::uuid[], c->'spec'->>'type',
      jsonb_strip_nulls(jsonb_build_object('values', c->'spec'->'values', 'items', c->'spec'->'items',
        'tax', c->'spec'->'tax', 'tip', c->'spec'->'tip', 'discount', c->'spec'->'discount')))) as shares
  from v, jsonb_array_elements(v.j->'oks') c
)
select 'split_shares' as check_name, count(*) filter (where shares = c->'shares') || '/' || count(*) as passed from tries
union all
select 'recurring_occurrence', count(*) filter (where public.recurring_occurrence((c->>0)::date, c->>1, (d.n - 1)::int)::text = d.dt) || '/' || count(*)
from v, jsonb_array_elements(v.j->'dates') c, unnest(string_to_array(c->>2, ',')) with ordinality d(dt, n);

